function KeywordDrill({ terms }) {
  const [order, setOrder] = useState(() => shuffle(terms));
  const [idx, setIdx] = useState(0);
  const [answer, setAnswer] = useState("");
  const [checked, setChecked] = useState(null);

  const current = order[idx];
  const done = idx >= order.length;

  function check() {
    if (!answer.trim() || checked) return;
    const isCorrect = normalizeAnswer(answer) === normalizeAnswer(current.es);
    setChecked(isCorrect ? "correct" : "wrong");
  }

  function next() {
    setAnswer("");
    setChecked(null);
    setIdx((i) => i + 1);
  }

  function restart() {
    setOrder(shuffle(terms));
    setIdx(0);
    setAnswer("");
    setChecked(null);
  }

  if (done) {
    return (
      <div
        className="rounded p-4 text-center"
        style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}
      >
        <p style={{ fontFamily: serif, fontSize: 18, color: C.text, margin: 0 }}>
          Terminaste los términos de este texto
        </p>
        <button
          onClick={restart}
          className="mt-3"
          style={{
            fontFamily: sans,
            fontSize: 15,
            padding: "6px 14px",
            borderRadius: 4,
            border: `1px solid ${C.border}`,
            backgroundColor: "transparent",
            color: C.text,
            cursor: "pointer",
          }}
        >
          Repetir
        </button>
      </div>
    );
  }

  return (
    <div
      className="rounded p-4"
      style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}
    >
      <p
        style={{
          fontFamily: serif,
          fontSize: 19,
          color: C.text,
          margin: 0,
        }}
      >
        {current.term}
      </p>

      <input
        value={answer}
        onChange={(e) => setAnswer(e.target.value)}
        onKeyDown={(e) => e.key === "Enter" && (checked ? next() : check())}
        placeholder="Escribe el equivalente en español..."
        disabled={!!checked}
        className="w-full rounded px-3 py-2 mt-3"
        style={{
          fontFamily: sans,
          fontSize: 16,
          color: C.text,
          backgroundColor: C.bg,
          border: `1px solid ${
            checked === "correct" ? C.success : checked === "wrong" ? C.error : C.border
          }`,
          outline: "none",
        }}
      />

      {checked && (
        <p
          style={{
            fontFamily: sans,
            fontSize: 15,
            color: checked === "correct" ? C.success : C.error,
            margin: "8px 0 0 0",
          }}
        >
          {checked === "correct" ? "Correcto." : `Sugerido: ${current.es}`}
        </p>
      )}

      <button
        onClick={checked ? next : check}
        className="mt-3"
        style={{
          fontFamily: sans,
          fontSize: 15,
          padding: "8px 16px",
          borderRadius: 4,
          border: "none",
          backgroundColor: C.accent,
          color: C.bg,
          cursor: "pointer",
        }}
      >
        {checked ? "Siguiente" : "Comprobar"}
      </button>
    </div>
  );
}

