function useIsMobile() {
  const [isMobile, setIsMobile] = useState(
    typeof window !== "undefined" ? window.innerWidth < 768 : false
  );
  useEffect(() => {
    function onResize() {
      setIsMobile(window.innerWidth < 768);
    }
    window.addEventListener("resize", onResize);
    onResize();
    return () => window.removeEventListener("resize", onResize);
  }, []);
  return isMobile;
}


// Tamaño de letra: escala solo el contenido principal, el menú se queda igual.
const ESCALAS = [1, 1.12, 1.25, 1.4];
const ESCALA_KEY = "palabraJusta_tamanoLetra";

function useEscala() {
  const [nivel, setNivel] = useState(() => {
    try {
      const n = Number(window.localStorage.getItem(ESCALA_KEY));
      return n >= 0 && n < ESCALAS.length ? n : 0;
    } catch (e) {
      return 0;
    }
  });
  useEffect(() => {
    try {
      window.localStorage.setItem(ESCALA_KEY, String(nivel));
    } catch (e) {}
  }, [nivel]);
  return [nivel, setNivel];
}

function TamanoLetra({ nivel, setNivel }) {
  const boton = (activo) => ({
    width: 34,
    height: 30,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    border: "none",
    background: "none",
    color: activo ? C.accent : C.label,
    opacity: activo ? 1 : 0.35,
    cursor: activo ? "pointer" : "default",
    fontFamily: serif,
    fontWeight: 600,
    lineHeight: 1,
    padding: 0,
  });
  return (
    <div
      role="group"
      aria-label="Tamaño de letra"
      title={`Tamaño de letra: ${Math.round(ESCALAS[nivel] * 100)}%`}
      style={{
        display: "inline-flex",
        alignItems: "center",
        border: `1px solid ${C.border}`,
        borderRadius: 999,
        backgroundColor: C.card,
        flexShrink: 0,
      }}
    >
      <button
        onClick={() => setNivel((n) => Math.max(0, n - 1))}
        disabled={nivel === 0}
        aria-label="Letra más pequeña"
        style={{ ...boton(nivel > 0), fontSize: 13 }}
      >
        A
      </button>
      <span style={{ width: 1, height: 16, backgroundColor: C.border }} />
      <button
        onClick={() => setNivel((n) => Math.min(ESCALAS.length - 1, n + 1))}
        disabled={nivel === ESCALAS.length - 1}
        aria-label="Letra más grande"
        style={{ ...boton(nivel < ESCALAS.length - 1), fontSize: 19 }}
      >
        A
      </button>
    </div>
  );
}

function InicioView({ irA }) {
  const accesos = [
    { id: "glosario", icon: ListChecks, titulo: "Glosario", texto: "815 términos en una sola búsqueda" },
    { id: "quiz", icon: ClipboardCheck, titulo: "Opción múltiple", texto: "Con opciones trampa" },
    { id: "escribir", icon: PenLine, titulo: "Escribir", texto: "Escribe la equivalencia exacta" },
    { id: "consecutiva", icon: Headphones, titulo: "Consecutiva", texto: "Práctica y autoevaluación" },
  ];
  return (
    <div>
      <h1 style={{ fontFamily: serif, fontWeight: 600, color: C.text, fontSize: 33, margin: 0 }}>
        Palabra Justa
      </h1>
      <p style={{ fontFamily: sans, color: C.muted, fontSize: 16, margin: "6px 0 0 0" }}>
        Elige una semana en el menú o empieza a practicar.
      </p>
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))",
          gap: 12,
          marginTop: 24,
        }}
      >
        {accesos.map(({ id, icon: Icon, titulo, texto }) => (
          <button
            key={id}
            onClick={() => irA(id)}
            style={{
              textAlign: "left",
              display: "flex",
              gap: 12,
              alignItems: "flex-start",
              padding: "16px 16px",
              backgroundColor: C.card,
              border: `1px solid ${C.border}`,
              borderLeft: `4px solid ${C.clay}`,
              borderRadius: 10,
              cursor: "pointer",
            }}
          >
            <Icon size={20} color={C.accent} style={{ flexShrink: 0, marginTop: 2 }} />
            <span>
              <span style={{ display: "block", fontFamily: sans, fontSize: 16, fontWeight: 600, color: C.text }}>
                {titulo}
              </span>
              <span style={{ display: "block", fontFamily: sans, fontSize: 14, color: C.muted, marginTop: 2 }}>
                {texto}
              </span>
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

